package ai.decisionos.aside;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.os.*;import org.json.*;
/** One foreground-only location sample, displayed before any model/server sharing. */
final class TravelLocation {
 static final int REQUEST=8252;static final Handler h=new Handler(Looper.getMainLooper());
 static boolean handle(GoalChatUi c,String text){if(!text.matches("(?is).*(현재|내).*(위치|속도).*(확인|조회|이동|KTX|기차|알려).*"))return false;sample(c);return true;}
 static boolean usable(Location l,long elapsedNow){return l!=null&&l.hasAccuracy()&&Float.isFinite(l.getAccuracy())&&l.getAccuracy()>=0&&l.getAccuracy()<=200&&Double.isFinite(l.getLatitude())&&Double.isFinite(l.getLongitude())&&Math.abs(l.getLatitude())<=90&&Math.abs(l.getLongitude())<=180&&elapsedNow-l.getElapsedRealtimeNanos()>=0&&elapsedNow-l.getElapsedRealtimeNanos()<=120000000000L;}
 static void sample(GoalChatUi c){GoalAgentActivity a=c.a;if(a.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&a.checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){a.requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},REQUEST);return;}if(Build.VERSION.SDK_INT<30){a.toast("이 기기에서는 최신 위치 조회를 지원하지 않아요.");return;}LocationManager manager=a.getSystemService(LocationManager.class);String provider=manager.isProviderEnabled(LocationManager.GPS_PROVIDER)?LocationManager.GPS_PROVIDER:manager.isProviderEnabled(LocationManager.NETWORK_PROVIDER)?LocationManager.NETWORK_PROVIDER:null;if(provider==null){a.toast("기기 위치 설정을 켜고 다시 요청해 주세요.");return;}CancellationSignal cancellation=new CancellationSignal();boolean[] done={false};Runnable timeout=()->{if(done[0])return;done[0]=true;cancellation.cancel();if(!a.isDestroyed())a.toast("최근 위치를 얻지 못했어요. 실외에서 다시 확인해 주세요.");};h.postDelayed(timeout,15000);a.toast("현재 위치를 한 번 확인하고 있어요.");try{manager.getCurrentLocation(provider,cancellation,a.getMainExecutor(),l->{if(done[0])return;done[0]=true;h.removeCallbacks(timeout);if(a.isDestroyed()||a.isFinishing())return;if(!usable(l,SystemClock.elapsedRealtimeNanos())){a.toast("위치가 오래됐거나 오차가 커서 이동 계산에 쓰지 않았어요.");return;}JSONObject data=new JSONObject();GoalStore.put(data,"observed_at",java.time.Instant.ofEpochMilli(l.getTime()).toString());GoalStore.put(data,"latitude",l.getLatitude());GoalStore.put(data,"longitude",l.getLongitude());GoalStore.put(data,"accuracy_m",l.getAccuracy());if(l.hasSpeed()&&Float.isFinite(l.getSpeed())&&l.getSpeed()>=0)GoalStore.put(data,"speed_mps",l.getSpeed());String body=data.toString();new AlertDialog.Builder(a).setTitle("현재 위치 확인").setMessage(body+"\n\n한 번 측정한 위치예요. 도로·버스 실제 이동시간과 다를 수 있어요. 위치만으로 KTX 표를 취소하지 않아요.").setNegativeButton("닫기",null).setPositiveButton("이 위치로 이동 조회 준비",(d,w)->c.draft("현재 측정한 위치를 사용해서 울산역까지 이동 경로와 KTX 시간표를 조회해줘. GPS 속도로 직선 ETA를 만들지 말고 실제 경로 API가 없으면 조회 불가라고 해. 예약·취소·결제는 하지 마.\n사용자 확인 위치: "+body)).show();});}catch(SecurityException denied){done[0]=true;h.removeCallbacks(timeout);a.toast("위치 권한을 확인해 주세요.");}}
}
